<script setup lang="ts">
import { onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { eliminarTipoComponente, guardarTipoComponente, listarTiposComponente } from '../services/tiposComponente'
import type { TipoComponente, TipoComponentePayload } from '../interfaces/tiposComponente.interface'
const records=ref<TipoComponente[]>([]),query=ref(''),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),preview=ref(''),fileInput=ref<HTMLInputElement>()
const categories=['Captación','Tratamiento','Almacenamiento','Distribución','Medición'],form=reactive<TipoComponentePayload>({nombre:'',categoria:'',puntos:1,color:'#e38b2f',grosor:3,descripcion:'',icono:null})
async function load(){loading.value=true;error.value='';try{records.value=await listarTiposComponente(query.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clearPreview(){if(preview.value.startsWith('blob:'))URL.revokeObjectURL(preview.value);preview.value=''}
function open(item?:TipoComponente){clearPreview();editing.value=item?.id??null;Object.assign(form,item?{nombre:item.nombre,categoria:item.categoria,puntos:item.puntos,color:item.color||'#e38b2f',grosor:item.grosor||3,descripcion:item.descripcion,icono:null}:{nombre:'',categoria:'',puntos:1,color:'#e38b2f',grosor:3,descripcion:'',icono:null});preview.value=item?.icono_url||'';modal.value=true}
function selectFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0]||null;if(file&&file.size>4*1024*1024){error.value='El icono no debe superar los 4 MB.';return}clearPreview();form.icono=file;if(file)preview.value=URL.createObjectURL(file)}
async function save(){if(!form.nombre.trim()){error.value='Ingrese el nombre del tipo de componente.';return}if(form.puntos<1){error.value='Debe requerirse al menos un punto.';return}saving.value=true;error.value='';try{await guardarTipoComponente({...form,nombre:form.nombre.trim(),descripcion:form.descripcion.trim()},editing.value??undefined);modal.value=false;success.value=`Tipo ${editing.value?'actualizado':'registrado'} correctamente.`;await load()}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:TipoComponente){if(item.componentes_count){error.value='No se puede eliminar porque existen componentes asociados.';return}if(!confirm(`¿Eliminar el tipo ${item.nombre}?`))return;try{await eliminarTipoComponente(item.id);success.value='Tipo de componente eliminado.';await load()}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
onMounted(load);onBeforeUnmount(clearPreview)
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Operaciones / Catastro Técnico / Tipos de componente</nav><header class="hero"><div class="mark">TC</div><div><small>DANA · CATASTRO TÉCNICO</small><h1>Tipos de componente</h1><p>Configura la clasificación y representación de la infraestructura.</p></div><button @click="open()">+ Crear tipo</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="tools"><input v-model.trim="query" placeholder="Nombre o descripción" @keyup.enter="load"><button @click="load">Buscar</button><span>{{records.length}} tipos encontrados</span></section><div v-if="loading" class="empty">Cargando tipos de componente…</div><div v-else-if="!records.length" class="empty">No hay tipos de componente que mostrar.</div><section v-else class="cards"><article v-for="item in records" :key="item.id"><header :style="{borderColor:item.color||'#e38b2f'}"><div class="symbol"><img v-if="item.icono_url" :src="item.icono_url" alt=""><i v-else :style="{background:item.color||'#e38b2f'}"></i></div><div><small>{{item.categoria||'SIN CATEGORÍA'}}</small><h2>{{item.nombre}}</h2></div><b>{{item.componentes_count}}</b></header><p>{{item.descripcion||'Sin descripción registrada.'}}</p><div class="style-info"><span><small>GEOMETRÍA</small><b>{{item.puntos===1?'Punto':`${item.puntos} puntos`}}</b></span><span><small>COLOR</small><b><i :style="{background:item.color}"></i>{{item.color}}</b></span><span><small>GROSOR</small><b>{{item.grosor}} px</b></span></div><div class="sample"><svg viewBox="0 0 300 35"><line v-if="item.puntos>1" x1="15" y1="18" x2="285" y2="18" :stroke="item.color" :stroke-width="item.grosor" stroke-linecap="round"/><circle v-else cx="150" cy="18" r="9" :fill="item.color" stroke="white" stroke-width="3"/></svg></div><footer><button class="edit" @click="open(item)">Modificar</button><button class="delete" :disabled="!!item.componentes_count" @click="remove(item)">Eliminar</button></footer></article></section>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>CATASTRO TÉCNICO</small><h2>{{editing?'Modificar':'Registrar'}} tipo de componente</h2></div><button type="button" @click="modal=false">×</button></header><div class="content"><div class="fields"><label>Nombre *<input v-model="form.nombre" maxlength="100" required></label><label>Categoría<select v-model="form.categoria"><option value="">Seleccione</option><option v-for="item in categories" :key="item">{{item}}</option></select></label><label>Puntos requeridos *<input v-model.number="form.puntos" type="number" min="1" required></label><label>Grosor del trazo<input v-model.number="form.grosor" type="number" min="1" max="20"></label><label>Color<input v-model="form.color" type="color"></label><label>Icono<input ref="fileInput" type="file" accept=".png,.jpg,.jpeg,.webp,.svg" @change="selectFile"></label><label class="wide">Descripción<textarea v-model="form.descripcion" rows="3"></textarea></label></div><aside><small>PREVISUALIZACIÓN</small><div class="preview"><img v-if="preview" :src="preview" alt=""><svg v-else viewBox="0 0 240 100"><line v-if="form.puntos>1" x1="20" y1="50" x2="220" y2="50" :stroke="form.color" :stroke-width="form.grosor" stroke-linecap="round"/><circle v-else cx="120" cy="50" r="16" :fill="form.color" stroke="white" stroke-width="5"/></svg></div><b>{{form.nombre||'Nombre del tipo'}}</b><span>{{form.puntos===1?'Elemento puntual':`Geometría de ${form.puntos} puntos`}}</span></aside></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':editing?'Actualizar':'Registrar'}}</button></footer></form></div></div></template>
